import { useId, useRef, useState,
    type ComponentProps, type ReactNode } from "react";
import { Button } from "./button";
import { cn } from "./utils";

type ApprovalStatus = "requested" | "approved" | "rejected" | "expired";
type ApprovalDecision = "approve" | "reject";
type PermissionDecision = "allow-once" | "allow-always" | "deny";

type PermissionDecisionOption = {
    decision: PermissionDecision;
    label?: string;
};

type ApprovalCardBaseProps = Omit<
    ComponentProps<"section">,
    "children" | "title"
> & {
    requestId: string;
    title: string;
    description: ReactNode;
    status: ApprovalStatus;
    decisionErrorMessage?: string;
};

type ApprovalCardLegacyProps = ApprovalCardBaseProps & {
    permissionDecisions?: never;
    permissionScope?: never;
    onPermissionDecision?: never;
    onDecision: (decision: ApprovalDecision, requestId: string) =>
        void | Promise<void>;
};

type ApprovalCardPermissionProps = ApprovalCardBaseProps & {
    permissionDecisions: readonly PermissionDecisionOption[];
    permissionScope: ReactNode;
    onDecision?: never;
    onPermissionDecision: (
        decision: PermissionDecision, requestId: string,
    ) => void | Promise<void>;
};

type ApprovalCardProps =
    | ApprovalCardLegacyProps
    | ApprovalCardPermissionProps;

const statusLabel: Record<ApprovalStatus, string> = {
    requested: "승인 요청",
    approved: "승인됨",
    rejected: "거절됨",
    expired: "요청 만료",
};

const permissionLabel: Record<PermissionDecision, string> = {
    "allow-once": "한 번 허용",
    "allow-always": "항상 허용",
    deny: "거부",
};

function isPermissionDecision(value: unknown): value is PermissionDecision {
    return value === "allow-once" || value === "allow-always" ||
        value === "deny";
}

function ApprovalCard(props: ApprovalCardProps) {
    const {
        requestId, title, description, status,
        decisionErrorMessage = "결정을 전달하지 못했습니다. 다시 시도하세요.",
        onDecision, onPermissionDecision, permissionDecisions,
        permissionScope,
        className, ...sectionProps
    } = props;
    const titleId = useId();
    const descriptionId = useId();
    const scopeId = useId();
    const pendingIds = useRef(new Set<string>());
    const submittedIds = useRef(new Set<string>());
    const [submissions, setSubmissions] = useState(new Map<
        string, "pending" | "sent" | "error"
    >());
    const permissionMode = permissionDecisions !== undefined;

    if (!requestId.trim()) {
        throw new Error("ApprovalCard requires a requestId.");
    }
    if (!title.trim()) {
        throw new Error("ApprovalCard requires a title.");
    }
    if (description == null || description === "") {
        throw new Error("ApprovalCard requires a description.");
    }
    if (!Object.hasOwn(statusLabel, status)) {
        throw new Error("ApprovalCard received an unsupported status.");
    }
    if (permissionMode) {
        if (!permissionDecisions.every((option) =>
            option && isPermissionDecision(option.decision))) {
            throw new Error("ApprovalCard received an unsupported permission decision.");
        }
        if (permissionScope == null || permissionScope === "") {
            throw new Error("ApprovalCard requires a permission scope.");
        }
    }

    const pending = pendingIds.current.has(requestId);
    const sent = submittedIds.current.has(requestId);
    const submission = submissions.get(requestId);
    const failed = submission === "error" && !pending && !sent;

    function setSubmissionFor(
        targetRequestId: string,
        phase: "pending" | "sent" | "error",
    ) {
        setSubmissions((previous) => new Map(previous).set(
            targetRequestId, phase,
        ));
    }

    async function decide(decision: ApprovalDecision | PermissionDecision) {
        if (status !== "requested" || pendingIds.current.has(requestId) ||
            submittedIds.current.has(requestId)) return;
        if (permissionMode) {
            if (!isPermissionDecision(decision) ||
                !permissionDecisions?.some((option) =>
                    option.decision === decision)) return;
        } else if (decision !== "approve" && decision !== "reject") {
            return;
        }

        pendingIds.current.add(requestId);
        setSubmissionFor(requestId, "pending");
        try {
            if (permissionMode) {
                if (isPermissionDecision(decision)) {
                    if (typeof onPermissionDecision !== "function") {
                        throw new TypeError("ApprovalCard requires an onPermissionDecision callback.");
                    }
                    await onPermissionDecision(decision, requestId);
                }
            } else if (decision === "approve" || decision === "reject") {
                if (typeof onDecision !== "function") {
                    throw new TypeError("ApprovalCard requires an onDecision callback.");
                }
                await onDecision(decision, requestId);
            }
            pendingIds.current.delete(requestId);
            submittedIds.current.add(requestId);
            setSubmissionFor(requestId, "sent");
        } catch {
            pendingIds.current.delete(requestId);
            setSubmissionFor(requestId, "error");
        }
    }

    const describedBy = permissionMode
        ? `${descriptionId} ${scopeId}` : descriptionId;

    return (
        <section {...sectionProps} aria-labelledby={titleId}
            data-ui="approval-card"
            aria-describedby={describedBy}
            aria-busy={pending}
            data-status={status}
            className={cn(
                "min-w-0 rounded-sm border border-border bg-surface " +
                "p-[var(--space-3)] text-foreground",
                className,
            )}>
            <div className="flex flex-wrap items-start justify-between gap-2">
                <h3 id={titleId} className="m-0 text-sm font-semibold">
                    {title}
                </h3>
                <span role="status" className={cn(
                    "text-xs",
                    status === "rejected" || status === "expired"
                        ? "text-muted" : "text-accent",
                )}>
                    {status === "requested" && pending ? "결정 전달 중…"
                        : status === "requested" && sent ? "결정 전달됨"
                            : statusLabel[status]}
                </span>
            </div>
            <div id={descriptionId}
                className="mt-[var(--space-2)] min-w-0 break-words text-sm text-muted">
                {description}
            </div>
            {permissionMode && (
                <p id={scopeId} data-slot="permission-scope"
                    className="m-0 mt-[var(--space-2)] text-xs text-muted">
                    <span className="font-medium">적용 범위:</span>{" "}
                    {permissionScope}
                </p>
            )}
            {status === "requested" && !sent && (
                <div className="mt-[var(--space-3)] flex flex-wrap gap-2">
                    {permissionMode ? permissionDecisions.map((option) => (
                        <Button key={option.decision}
                            variant={option.decision === "deny"
                                ? "outline" : "primary"}
                            disabled={pending}
                            onClick={() => void decide(option.decision)}>
                            {option.label ?? permissionLabel[option.decision]}
                        </Button>
                    )) : <>
                        <Button disabled={pending}
                            onClick={() => void decide("approve")}>
                            승인
                        </Button>
                        <Button variant="outline" disabled={pending}
                            onClick={() => void decide("reject")}>
                            거절
                        </Button>
                    </>}
                </div>
            )}
            {status === "requested" && failed && (
                <p role="alert" className={
                    "m-0 mt-[var(--space-2)] text-sm text-danger"
                }>
                    {decisionErrorMessage}
                </p>
            )}
        </section>
    );
}

export { ApprovalCard };
export type {
    ApprovalCardProps, ApprovalDecision, ApprovalStatus,
    PermissionDecision, PermissionDecisionOption,
};
